import { getDocumentsForCustomer } from '@/modules/crm/document/document.service';
import { DocumentList } from '@/components/crm/DocumentList';
import { DocumentUploader } from '@/components/crm/DocumentUploader';

export async function DocumentsTabWrapper({ customerId }: { customerId: string }) {
  const documents = await getDocumentsForCustomer(customerId);
  
  return (
    <div className="glass-panel p-6 flex flex-col gap-6 animate-in fade-in duration-500">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <h3 className="text-lg font-display font-semibold text-white">Documents</h3>
          <p className="text-sm text-[#8891B0] mt-0.5">Manage and attach files relevant to this customer.</p>
        </div>
        <DocumentUploader customerId={customerId} />
      </div>
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
      // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
      <DocumentList documents={documents as any} customerId={customerId} />
    </div>
  );
}

import { Suspense } from 'react';
import { getCustomersAction } from '@/modules/crm/actions/customer.actions';
import { CustomerForm } from '@/components/crm/CustomerForm';
import Link from 'next/link';
import { CustomerActions } from '@/components/crm/CustomerActions';
import { Badge } from '@/components/ui/Badge';
import { Button } from '@/components/ui/button';
import { Users } from 'lucide-react';
import { EmptyState } from '@/components/ui/EmptyState';
import { FilterBar } from '@/components/crm/FilterBar';
import { PaginationButton } from '@/components/crm/PaginationButton';
import { Skeleton } from '@/components/ui/Skeleton';

export default async function CustomersPage(props: {
  searchParams: Promise<{ [key: string]: string | string[] | undefined }>;
}) {
  const searchParams = await props.searchParams;
  const search   = typeof searchParams.search   === 'string' ? searchParams.search   : undefined;
  const status   = typeof searchParams.status   === 'string' ? searchParams.status   : undefined;
  const industry = typeof searchParams.industry === 'string' ? searchParams.industry : undefined;
  const cursor   = typeof searchParams.cursor   === 'string' ? searchParams.cursor   : undefined;

  const result = await getCustomersAction({
    search,
    cursor,
    limit: 50,
    filters: {
      ...(status   ? { status }   : {}),
      ...(industry ? { industry } : {}),
    },
  });

  const resData   = result.success ? (result.data || []) : [];
  const customers = Array.isArray(resData) ? resData : (resData.data || []);
  const pagination = !Array.isArray(resData) ? resData.pagination : null;

  return (
    <div className="space-y-6 animate-in">

      {/* ─── Page header ─── */}
      <div className="glass-panel rounded-[1.25rem] p-5 flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <p className="font-display font-bold text-xl text-white">Enterprise Customers</p>
          <p className="text-sm mt-1" style={{ color: '#8891B0' }}>
            Manage your B2B accounts and relationships.
          </p>
        </div>
        <div className="shrink-0">
          <CustomerForm />
        </div>
      </div>

      {/* ─── Table panel ─── */}
      <div
        className="rounded-[1.1rem] border border-white/[.08] overflow-hidden"
        style={{
          background: 'linear-gradient(180deg, rgba(27,35,64,.65), rgba(13,19,38,.65))',
          boxShadow: '0 8px 32px rgba(0,0,0,.35)',
        }}
      >
        {/* Toolbar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 px-5 py-4 border-b border-white/[.05]">
          <p className="font-display font-semibold text-white">Customer Directory</p>
          <FilterBar
            filters={[
              {
                key: 'status',
                label: 'All Statuses',
                options: [
                  { label: 'Active',   value: 'ACTIVE'   },
                  { label: 'Inactive', value: 'INACTIVE' },
                  { label: 'Pending',  value: 'PENDING'  },
                ],
              },
              {
                key: 'industry',
                label: 'All Industries',
                options: [
                  { label: 'Technology', value: 'Technology' },
                  { label: 'Finance',    value: 'Finance'    },
                  { label: 'Healthcare', value: 'Healthcare' },
                  { label: 'Retail',     value: 'Retail'     },
                ],
              },
            ]}
          />
        </div>

        {/* Table */}
        <Suspense
          fallback={
            <div className="space-y-3 p-4">
              {[1, 2, 3, 4].map((i) => (
                <Skeleton key={i} className="h-12 w-full" />
              ))}
            </div>
          }
        >
          <div className="overflow-x-auto">
            <table className="data-table w-full text-sm">
              <thead>
                <tr className="text-left border-b border-white/[.05]">
                  <th className="py-3 px-4">Company Name</th>
                  <th className="py-3 px-4 hidden md:table-cell">Industry</th>
                  <th className="py-3 px-4">Status</th>
                  <th className="py-3 px-4 text-right">Actions</th>
                </tr>
              </thead>
              <tbody>
                {customers.length === 0 && (
                  <tr>
                    <td colSpan={4} className="p-0">
                      <EmptyState
                        title="No Customers Found"
                        description="Your CRM is ready. Add your first enterprise customer to begin."
                        icon={<Users className="w-6 h-6" />}
                      />
                    </td>
                  </tr>
                )}
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                {customers.map((customer: any) => (
                  <tr
                    key={customer.id}
                    className="border-b border-white/[.05] last:border-0 group"
                  >
                    <td className="py-3 px-4">
                      <div className="flex items-center gap-3">
                        <div
                          className="w-8 h-8 rounded-xl flex items-center justify-center text-white text-xs font-bold shrink-0"
                          style={{ background: 'linear-gradient(135deg,#7C5CFC,#9B7BFF)' }}
                        >
                          {customer.name?.[0]?.toUpperCase() || 'C'}
                        </div>
                        <div>
                          <p className="font-medium text-white">{customer.name}</p>
                          <p className="text-xs text-slate-400 md:hidden">{customer.industry || '—'}</p>
                        </div>
                      </div>
                    </td>
                    <td className="py-3 px-4 hidden md:table-cell text-slate-400">
                      {customer.industry || '—'}
                    </td>
                    <td className="py-3 px-4">
                      <Badge variant={customer.status === 'ACTIVE' ? 'emerald' : 'slate'}>
                        {customer.status?.replace(/_/g, ' ') || 'Active'}
                      </Badge>
                    </td>
                    <td className="py-3 px-4 text-right">
                      <div className="flex items-center justify-end gap-2 opacity-0 group-hover:opacity-100 transition-opacity">
                        <Link href={`/customers/${customer.id}`}>
                          <Button variant="ghost" size="sm">View</Button>
                        </Link>
                        <CustomerActions customerId={customer.id} />
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>

          {/* Footer */}
          <div
            className="flex items-center justify-between px-4 py-3 text-xs border-t border-white/[.05]"
            style={{ color: '#8891B0' }}
          >
            <span>Showing {customers.length} customers</span>
          </div>

          {pagination && (
            <PaginationButton
              hasMore={pagination.hasMore}
              nextCursor={pagination.nextCursor}
            />
          )}
        </Suspense>
      </div>
    </div>
  );
}

import { getDepartments } from '@/modules/departments/department.service';
import { requireAuth } from '@/lib/auth';
import { DepartmentForm } from '@/components/departments/DepartmentForm';

export default async function DepartmentsPage() {
  const actor = await requireAuth();
  
  let isTenantAdmin = false;
  for (const ur of actor.userRoles) {
    if (ur.role.name === 'TENANT_ADMIN') isTenantAdmin = true;
  }

  const departments = await getDepartments();

  return (
    <div className="p-6 max-w-6xl mx-auto min-h-screen bg-slate-50 dark:bg-slate-950 font-sans text-slate-900 dark:text-slate-100">
      <div className="flex justify-between items-center mb-8">
        <div>
          <h1 className="text-3xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-blue-500 to-indigo-600">Departments</h1>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Organize your organization structure.</p>
        </div>
        {isTenantAdmin && (
          <DepartmentForm />
        )}
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
        // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
        {departments.map((dept: any) => (
          <div key={dept.id} className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 p-6 shadow-sm hover:shadow-md transition-all flex flex-col h-full group">
            <div className="flex justify-between items-start mb-4">
              <div className="w-12 h-12 rounded-xl bg-indigo-50 dark:bg-indigo-500/10 flex items-center justify-center text-indigo-600 dark:text-indigo-400">
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 20V4a2 2 0 0 0-2-2h-4a2 2 0 0 0-2 2v16"/><path d="m22 20-2-2-4 4-4-4-2 2-4-4-4 4"/><path d="M4 14v6"/><path d="M4 10v.01"/><path d="M4 6v.01"/><path d="M20 14v6"/><path d="M20 10v.01"/><path d="M20 6v.01"/></svg>
              </div>
              {isTenantAdmin && (
                <DepartmentForm initialData={{ id: dept.id, name: dept.name, description: dept.description }} />
              )}
            </div>
            
            <h3 className="text-lg font-bold mb-2">{dept.name}</h3>
            <p className="text-sm text-slate-500 dark:text-slate-400 flex-grow">{dept.description || 'No description provided.'}</p>
            
            <div className="mt-6 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">
              <div className="flex items-center gap-2">
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                <svg className="w-4 h-4 text-slate-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2"/><circle cx="9" cy="7" r="4"/><path d="M22 21v-2a4 4 0 0 0-3-3.87"/><path d="M16 3.13a4 4 0 0 1 0 7.75"/></svg>
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                <span className="text-sm font-medium text-slate-600 dark:text-slate-300">{(dept as any)._count?.users || 0} Employees</span>
              </div>
            </div>
          </div>
        ))}
        
        {departments.length === 0 && (
          <div className="col-span-full py-12 text-center text-slate-500 bg-slate-100 dark:bg-slate-800/50 rounded-2xl border border-dashed border-slate-300 dark:border-slate-700">
            No departments configured yet.
          </div>
        )}
      </div>
    </div>
  );
}

import { requireAuth } from '@/lib/auth';
import prisma from '@db/utils/prisma';
import { notFound } from 'next/navigation';
import Link from 'next/link';
import { RoleEditModal } from '@/components/crm/RoleEditModal';
import { disableEmployeeAction } from '../actions';
import { EditProfileForm } from '@/components/employees/EditProfileForm';
import { ReassignDepartmentForm } from '@/components/employees/ReassignDepartmentForm';

export default async function EmployeeProfilePage({ params }: { params: Promise<{ employeeId: string } > }) {
  const resolvedParams = await params;
  const actor = await requireAuth();
  
  const employee = await prisma.user.findFirst({
    where: { id: decodeURIComponent(resolvedParams.employeeId), tenantId: actor.tenantId },
    include: { department: true, userRoles: { include: { role: true } } }
  });

  const departments = await prisma.department.findMany({ where: { tenantId: actor.tenantId } });

  if (!employee) return notFound();

  let isTenantAdmin = false;
  let isDepartmentHead = false;
  for (const ur of actor.userRoles) {
    if (ur.role.name === 'TENANT_ADMIN') isTenantAdmin = true;
    if (ur.role.name === 'DEPARTMENT_HEAD') isDepartmentHead = true;
  }

  // Permissions
  const isSelf = actor.id === employee.id;
  const canEditProfile = isSelf || isTenantAdmin;
  const canManageRole = isTenantAdmin;
  const canManageDept = isTenantAdmin || (isDepartmentHead && actor.departmentId === employee.departmentId);
  const canDisableEmployee = (isTenantAdmin || (isDepartmentHead && actor.departmentId === employee.departmentId)) && !isSelf;

  return (
    <div className="max-w-4xl mx-auto p-6 min-h-screen font-sans">
      <div className="mb-8 flex items-center gap-4">
        <Link href="/employees" className="p-2 bg-slate-100 dark:bg-slate-800 rounded-lg hover:bg-slate-200 dark:hover:bg-slate-700 transition-colors">
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </Link>
        <h1 className="text-2xl font-bold text-slate-900 dark:text-white">Employee Profile</h1>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        {/* Left Column: Identity Card */}
        <div className="md:col-span-1 space-y-6">
          <div className="bg-white dark:bg-slate-900 p-6 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col items-center text-center">
            <div className="w-24 h-24 rounded-full bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white text-3xl font-bold shadow-lg mb-4">
              {employee.firstName?.[0] || employee.email[0].toUpperCase()}
            </div>
            <h2 className="text-xl font-bold text-slate-900 dark:text-white">
              {employee.firstName ? `${employee.firstName} ${employee.lastName || ''}` : 'Unnamed Employee'}
            </h2>
            <p className="text-sm text-slate-500 mb-4">{employee.designation || 'No Designation'}</p>
            
            <div className="flex gap-2 flex-wrap justify-center mb-6">
              <span className="px-2.5 py-1 rounded-full text-xs font-semibold bg-slate-100 text-slate-600 dark:bg-slate-800 dark:text-slate-300">
                {employee.employeeId || 'PENDING'}
              </span>
              <span className={`px-2.5 py-1 rounded-full text-xs font-semibold
                ${employee.status === 'ACTIVE' ? 'bg-emerald-100 text-emerald-700 dark:bg-emerald-500/10 dark:text-emerald-400' : 'bg-rose-100 text-rose-700 dark:bg-rose-500/10 dark:text-rose-400'}`}>
                {employee.status}
              </span>
            </div>

            <div className="w-full pt-4 border-t border-slate-100 dark:border-slate-800">
              <div className="flex justify-between items-center text-sm mb-2">
                <span className="text-slate-500">Department</span>
                <span className="font-medium text-slate-900 dark:text-white">{employee.department?.name || 'Unassigned'}</span>
              </div>
              <div className="flex justify-between items-center text-sm">
                <span className="text-slate-500">Roles</span>
                <span className="font-medium text-slate-900 dark:text-white">
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                  {employee.userRoles.map((r: any) => r.role.name.replace('_', ' ')).join(', ')}
                </span>
              </div>
            </div>
          </div>
        </div>

        {/* Right Column: Editable Profile Details */}
        <div className="md:col-span-2 space-y-6">
          <div className="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">
            <div className="p-6 border-b border-slate-100 dark:border-slate-800 flex justify-between items-center">
              <h3 className="text-lg font-bold text-slate-900 dark:text-white">Contact & Details</h3>
              {canEditProfile && (
                <EditProfileForm 
                  userId={employee.id} 
                  initialData={{
                    firstName: employee.firstName,
                    lastName: employee.lastName,
                    phone: employee.phone,
                    designation: employee.designation
                  }} 
                />
              )}
            </div>
            <div className="p-6 grid grid-cols-1 sm:grid-cols-2 gap-6">
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Email Address</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">{employee.email}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Phone Number</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">
                  {/* Privacy: Only show phone if self or admin */}
                  {canEditProfile ? (employee.phone || 'Not provided') : '••••••••••'}
                </div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">First Name</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">{employee.firstName || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Last Name</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">{employee.lastName || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Designation</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">{employee.designation || '-'}</div>
              </div>
              <div>
                <label className="block text-xs font-medium text-slate-500 uppercase tracking-wider mb-1">Joined Date</label>
                <div className="text-sm font-medium text-slate-900 dark:text-slate-100">{new Date(employee.createdAt).toLocaleDateString()}</div>
              </div>
            </div>
          </div>

          {/* Admin Management Section */}
          {(canManageRole || canManageDept) && (
            <div className="bg-rose-50/50 dark:bg-rose-900/10 rounded-2xl border border-rose-100 dark:border-rose-900/30 shadow-sm p-6">
              <h3 className="text-lg font-bold text-rose-900 dark:text-rose-400 mb-4">Management Actions</h3>
              <div className="flex flex-wrap gap-4">
                {canManageRole && (
                  <RoleEditModal 
                    userId={employee.id} 
                    currentRole={employee.userRoles[0]?.role.name || 'MEMBER'} 
                  />
                )}
                {canManageDept && (
                  <ReassignDepartmentForm 
                    userId={employee.id} 
                    currentDepartmentId={employee.departmentId} 
                    departments={departments.map(d => ({ id: d.id, name: d.name }))} 
                  />
                )}
                // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                {canDisableEmployee && employee.status === 'ACTIVE' && (
                  // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
                  <form action={disableEmployeeAction.bind(null, employee.id) as any}>
                    <button type="submit" className="px-4 py-2 bg-white dark:bg-slate-800 border border-rose-200 dark:border-rose-900/50 rounded-lg text-sm font-medium text-rose-600 dark:text-rose-400 hover:bg-rose-50 dark:hover:bg-rose-900/20 transition-colors">
                      Disable Employee
                    </button>
                  </form>
                )}
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { getEmployees } from '@/modules/users/user.service';
import { getDepartments } from '@/modules/departments/department.service';
import { requireAuth } from '@/lib/auth';
import Link from 'next/link';
import { InviteEmployeeForm } from '@/components/employees/InviteEmployeeForm';

export default async function EmployeesPage(props: { searchParams: Promise<{ [key: string]: string | string[] | undefined }> }) {
  const actor = await requireAuth();
  
  // Parse Search Params
  const searchParams = await props.searchParams;
  const search = typeof searchParams.search === 'string' ? searchParams.search : undefined;
  const departmentId = typeof searchParams.departmentId === 'string' ? searchParams.departmentId : undefined;
  const roleName = typeof searchParams.roleName === 'string' ? searchParams.roleName : undefined;
  const status = typeof searchParams.status === 'string' ? searchParams.status : undefined;

  const [employees, departments] = await Promise.all([
    getEmployees({ search, departmentId, roleName, status }),
    getDepartments()
  ]);

  let isTenantAdmin = false;
  let isDepartmentHead = false;
  for (const ur of actor.userRoles) {
    if (ur.role.name === 'TENANT_ADMIN') isTenantAdmin = true;
    if (ur.role.name === 'DEPARTMENT_HEAD') isDepartmentHead = true;
  }
  const canManage = isTenantAdmin || isDepartmentHead;

  return (
    <div className="flex flex-col gap-6 p-6 min-h-screen bg-slate-50 dark:bg-slate-950 text-slate-900 dark:text-slate-100 font-sans">
      <div className="flex flex-col md:flex-row justify-between items-start md:items-center gap-4">
        <div>
          <h1 className="text-3xl font-bold tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-indigo-500 to-purple-600">Employee Directory</h1>
          <p className="text-sm text-slate-500 dark:text-slate-400 mt-1">Manage and view company personnel.</p>
        </div>
        {canManage && (
          <InviteEmployeeForm departments={departments} />
        )}
      </div>

      {/* Filters (Basic Implementation) */}
      <div className="bg-white dark:bg-slate-900 p-4 rounded-2xl shadow-sm border border-slate-200 dark:border-slate-800 flex flex-wrap gap-4 items-center">
        <form className="flex-1 min-w-[200px]" method="GET">
          <div className="relative">
            <input 
              name="search"
              defaultValue={search}
              placeholder="Search by name, email, or ID..." 
              className="w-full pl-10 pr-4 py-2.5 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent transition-all outline-none"
            />
            <svg className="absolute left-3.5 top-3 w-4 h-4 text-slate-400" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>
          </div>
        </form>
        {/* Simple Department Filter Dropdown (Client Component could enhance this) */}
        <select className="py-2.5 px-4 bg-slate-50 dark:bg-slate-950 border border-slate-200 dark:border-slate-800 rounded-xl text-sm focus:ring-2 focus:ring-indigo-500 transition-all outline-none">
          <option value="">All Departments</option>
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
          // eslint-disable-next-line @typescript-eslint/no-explicit-any -- S2 Residual Debt: Legacy internal payload requires architectural typing
          {departments.map((d: any) => <option key={d.id} value={d.id}>{d.name}</option>)}
        </select>
