                <thead>
                  <tr className="border-b border-white/10">
                    <th className="pb-3 font-medium text-[#8891B0]">Product</th>
                    <th className="pb-3 font-medium text-[#8891B0]">Qty</th>
                    <th className="pb-3 font-medium text-[#8891B0]">Unit Price</th>
